(function(){var s=document.currentScript,e=document.createElement('script');e.type='application/json';e.id="experiment-data";e.textContent="{\"001\":{\"title\":\"Box を山にして細分割し、位置で色を付ける\",\"href\":\"log.html#exp001\"},\"002\":{\"title\":\"subdivide の回数で、形と数はどう変わるか\",\"href\":\"log.html#exp002\"},\"003\":{\"title\":\"mountain と subdivide は、順序を変えると何が変わるか\",\"href\":\"log.html#exp003\"},\"004\":{\"title\":\"mountain のノイズパラメータは、それぞれ何に効くのか\",\"href\":\"log.html#exp004\"},\"005\":{\"title\":\"basis 14通りで、形はどこまで変わるか\",\"href\":\"log.html#exp005\"},\"006\":{\"title\":\"height は純粋な倍率か。gain と bias は何に効くか\",\"href\":\"log.html#exp006\"},\"007\":{\"title\":\"平面で地形を作り、指標を作り直す\",\"href\":\"log.html#exp007\"},\"008\":{\"title\":\"scatter と copy to points — 地面に物を生やす\",\"href\":\"log.html#exp008\"},\"009\":{\"title\":\"attribute wrangle で VEX を書く\",\"href\":\"log.html#exp009\"},\"010\":{\"title\":\"for-each ループと VEX を比べる\",\"href\":\"log.html#exp010\"},\"011\":{\"title\":\"crease で角を残す — どれだけの重みが要るのか\",\"href\":\"log.html#exp011\"},\"012\":{\"title\":\"polyextrude と boolean — 硬い形を作る\",\"href\":\"log.html#exp012\"},\"013\":{\"title\":\"時間軸への対応 — フレームを進めて記録する\",\"href\":\"log_fx.html#exp013\"},\"014\":{\"title\":\"RBD 破壊 — 最初の本物のシミュレーション\",\"href\":\"log_fx.html#exp014\"},\"015\":{\"title\":\"Vellum クロス — 布で保存されるべき量は何か\",\"href\":\"log_fx.html#exp015\"},\"016\":{\"title\":\"Pyro 煙 — dissipation の正体を式で突き止める\",\"href\":\"log_fx.html#exp016\"},\"017\":{\"title\":\"FLIP 液体 — 組み方が分からず保留\",\"href\":\"log_fx.html#exp017\"},\"018\":{\"title\":\"Karma でのレンダリング — ノイズはサンプル数で本当に減るのか\",\"href\":\"log_fx.html#exp018\"},\"019\":{\"title\":\"FLIP 液体 — 配線が解けた。そして粒の数は体積ではなかった\",\"href\":\"log_fx.html#exp019\"},\"020\":{\"title\":\"POP パーティクル — 生まれる数と落ち方を式で確かめる\",\"href\":\"log_fx.html#exp020\"},\"021\":{\"title\":\"煙はなぜ動かなかったのか — 温度を入れると立ち上る\",\"href\":\"log_fx.html#exp021\"},\"022\":{\"title\":\"液体に表面を張る — そして019の係数が間違っていた\",\"href\":\"log_fx.html#exp022\"},\"023\":{\"title\":\"炎を出す — shredding が効かなかった理由\",\"href\":\"log_fx.html#exp023\"},\"024\":{\"title\":\"動く煙で撮り直す — 018の結論は変わらなかった\",\"href\":\"log_fx.html#exp024\"},\"025\":{\"title\":\"シミュレーションのキャッシュ — 速くなるが、値は変わっていないか\",\"href\":\"log_fx.html#exp025\"},\"026\":{\"title\":\"炎に色を付ける — 黒体放射の式を、数字で追う\",\"href\":\"log_fx.html#exp026\"},\"027\":{\"title\":\"キャッシュを道具に組み込む — 古いファイルを読む事故を防ぐ\",\"href\":\"log_fx.html#exp027\"},\"028\":{\"title\":\"布は破れなかった — 効かない条件を14通り潰す\",\"href\":\"log_fx.html#exp028\"},\"029\":{\"title\":\"粒に力をかける — 風は「押す」のではなく「追いつかせる」\",\"href\":\"log_fx.html#exp029\"},\"030\":{\"title\":\"過去29回を測り直す — 書いたことは、いまも正しいか\",\"href\":\"log.html#exp030\"},\"031\":{\"title\":\"Vellum の breaking は動く — ただし布の伸びには効かない\",\"href\":\"log_fx.html#exp031\"},\"032\":{\"title\":\"狙った線で破れる布 — 先に切って、あとから貼る\",\"href\":\"log_fx.html#exp032\"},\"033\":{\"title\":\"布を物にぶつけて破る — 破れ始めは当たった場所、そのあとは全体へ\",\"href\":\"log_fx.html#exp033\"},\"034\":{\"title\":\"HeightField で地形を作る — 高さを面ではなく数の並びで持つ\",\"href\":\"log.html#exp034\"},\"035\":{\"title\":\"地形の上に生やし分ける — 浸食が残した情報で木の場所を決める\",\"href\":\"log.html#exp035\"},\"036\":{\"title\":\"流れの向きに草を寝かせる — flowdir は x と y が入れ替わっている\",\"href\":\"log.html#exp036\"},\"037\":{\"title\":\"浸食のレイヤーで地形を塗り分ける — 色は情報を持っているか\",\"href\":\"log.html#exp037\"},\"038\":{\"title\":\"塗り分けた地形を Karma で出す — 見立ては外れ、白飛びが本命だった\",\"href\":\"log.html#exp038\"},\"039\":{\"title\":\"Copernicus でテクスチャを作る — 細かさは解像度をどう食うのか\",\"href\":\"log.html#exp039\"},\"040\":{\"title\":\"作ったテクスチャを地形に貼る — 貼れたかどうかを画の数字で判定する\",\"href\":\"log.html#exp040\"},\"041\":{\"title\":\"凸凹の付け方3通り — 輪郭を見れば、どれが本当に形を変えたか分かる\",\"href\":\"log.html#exp041\"},\"042\":{\"title\":\"毛を生やす — density は本数ではなく「面積あたりの本数」だった\",\"href\":\"log.html#exp042\"},\"043\":{\"title\":\"毛を束ねる — つなぐ順番が、思っていたのと逆だった\",\"href\":\"log.html#exp043\"},\"044\":{\"title\":\"つないだのに、ガイドが1本も使われていなかった — rest が (0,0,0) だった\",\"href\":\"log.html#exp044\"},\"045\":{\"title\":\"毛を Karma で出す — 既定の太さは、画の上で 0.1ピクセルしかなかった\",\"href\":\"log.html#exp045\"},\"046\":{\"title\":\"毛に色を付ける — 光を消して測ると、色は位置ぴったりに乗った\",\"href\":\"log.html#exp046\"},\"047\":{\"title\":\"土台が動いたとき、毛は付いてくるのか — 入力をひとつつなぐかどうかだけの差\",\"href\":\"log.html#exp047\"},\"048\":{\"title\":\"毛を揺らす — 曲がりにくさは「垂れる距離」ではなく「形」に効いていた\",\"href\":\"log.html#exp048\"},\"049\":{\"title\":\"毛に風を当てる — 実験029と同じ「二次の抵抗」だった\",\"href\":\"log.html#exp049\"},\"050\":{\"title\":\"APEX に入る — 2,220個の部品と、いちばん小さいグラフ\",\"href\":\"log.html#exp050\"},\"051\":{\"title\":\"骨を作って動かす — rotate と prerotate を取り違えると、関節ごと飛んでいく\",\"href\":\"log.html#exp051\"},\"052\":{\"title\":\"骨に肉を付ける — 曲げると痩せる。減り方は (1 − cos θ) にぴたり乗った\",\"href\":\"log.html#exp052\"},\"053\":{\"title\":\"痩せない曲げ方はあった — Dual Quaternion で体積の減りが 154分の1 になる\",\"href\":\"log.html#exp053\"},\"054\":{\"title\":\"なぜ Linear が既定なのか — 速さではなかった。差は 4%\",\"href\":\"log.html#exp054\"},\"055\":{\"title\":\"逆運動学（IK）— 届かない場所を指すと、伸びきってそこで止まる\",\"href\":\"log.html#exp055\"},\"056\":{\"title\":\"長い鎖の IK — 式は同じ。ただし解き方は2種類あり、得意な範囲が逆\",\"href\":\"log.html#exp056\"},\"057\":{\"title\":\"APEX のグラフを持ち歩く — ネットワークが、そのままジオメトリになる\",\"href\":\"log.html#exp057\"},\"058\":{\"title\":\"Apprentice で外へ出せる形式 — FBX も glTF も Alembic も止まる\",\"href\":\"log.html#exp058\"},\"059\":{\"title\":\"obj で渡せる範囲 — 色と UV は残る。自作のアトリビュートは全部落ちる\",\"href\":\"log.html#exp059\"},\"060\":{\"title\":\"031〜059 の振り返り点検 — 6件すべて一致。1件は「もっと強い結論」に変わった\",\"href\":\"log.html#exp060\"},\"061\":{\"title\":\"MPM に入る — 落ち方は式に乗る。ただし時刻が 0.0742フレーム先に進んでいる\",\"href\":\"log_fx.html#exp061\"},\"062\":{\"title\":\"MPM でぶつける — 砂は 16% 膨らみ、既定の塊は 31% 縮む\",\"href\":\"log_fx.html#exp062\"},\"063\":{\"title\":\"MPM の粒を面に戻す — 27% 太る。膨らむ厚みは粒の間隔の 0.4倍\",\"href\":\"log_fx.html#exp063\"},\"064\":{\"title\":\"MPM の刻みを細かくする — 量によって、落ち着く速さが違った\",\"href\":\"log_fx.html#exp064\"},\"065\":{\"title\":\"MPM の粒を細かくする — 刻みより粒のほうが効くし、しかも安い\",\"href\":\"log_fx.html#exp065\"},\"066\":{\"title\":\"MPM の風 — 風速だけ上げても何も起きない。抵抗は速さの2乗だった\",\"href\":\"log_fx.html#exp066\"},\"067\":{\"title\":\"MPM の地面の摩擦 — 教科書の式に 0.04% で乗る。ただし塊が潰れるまで\",\"href\":\"log_fx.html#exp067\"},\"068\":{\"title\":\"MPM の材質5つで滑らせる — 摩擦の式に乗るのは、形が崩れない材質だけ\",\"href\":\"log_fx.html#exp068\"},\"069\":{\"title\":\"MPM のコライダの摩擦 — 式は同じ。ただし地面と重ねると完全に無視される\",\"href\":\"log_fx.html#exp069\"},\"070\":{\"title\":\"動く板は塊をどれだけ運ぶか — 追いつくまでは式どおり。追いついた先で潰れて遅れる\",\"href\":\"log_fx.html#exp070\"},\"071\":{\"title\":\"回る台は塊をどこまで乗せておけるか — 境目は式の形どおり。ただし摩擦は 0.3〜0.4 ぶんしか効かない\",\"href\":\"log_fx.html#exp071\"},\"072\":{\"title\":\"たわむ板は塊を放り上げられるか — Deforming は板の速さを渡す。Rigid はたわみを平均の動きにしてしまう\",\"href\":\"log_fx.html#exp072\"},\"073\":{\"title\":\"液体はいつ暴れ出すか — 摩擦の境目ではなく「時間」だった。substep 8 で消えるが 5倍かかる\",\"href\":\"log_fx.html#exp073\"},\"074\":{\"title\":\"sticky は天井にぶら下げられるか — 地面とコライダで効き方は同じ。ただし重さに逆らう力は無い\",\"href\":\"log_fx.html#exp074\"},\"075\":{\"title\":\"摩擦の上限は、粒の細かさで上がる — substep を 8 にしても1ミリも動かない\",\"href\":\"log_fx.html#exp075\"},\"076\":{\"title\":\"粒を細かくしても、摩擦の式には戻らない — 細かいほど塊が潰れ、かえって式から離れる\",\"href\":\"log_fx.html#exp076\"},\"077\":{\"title\":\"測る処理が、計算より重くなっていた — 1粒ずつ読むのをやめると 740倍速い\",\"href\":\"log_fx.html#exp077\"},\"078\":{\"title\":\"液体の暴れは、粒を細かくしても消えない — 飛ぶ高さは下がるが、始まる時刻は変わらない\",\"href\":\"log_fx.html#exp078\"},\"079\":{\"title\":\"火花を散らす — Life Variance は幅、Variance は球の半径。空気抵抗は速さの2乗で効く\",\"href\":\"log_fx.html#exp079\"},\"080\":{\"title\":\"雨を地面で跳ねさせる — Bounce は速さの比で、地面と粒の値は掛け算になる\",\"href\":\"log_fx.html#exp080\"},\"081\":{\"title\":\"旗を風になびかせる — 風速 2 まではほぼ垂れたまま。持ち上がり方は「抵抗 × 風速²」でそろう\",\"href\":\"log_fx.html#exp081\"},\"082\":{\"title\":\"道に沿って物を並べる — N だけでは坂で杭が倒れる。up を足せば 0度。Pack で 250倍速い\",\"href\":\"log.html#exp082\"},\"083\":{\"title\":\"看板の文字を立体にする — Distance はそのまま奥行き。角の丸めは 0.08 で止まる\",\"href\":\"log.html#exp083\"},\"084\":{\"title\":\"ドミノを倒す — 間隔は高さの 0.25〜1.03倍。初速は点に付けないと効かない\",\"href\":\"log_fx.html#exp084\"},\"085\":{\"title\":\"壁を崩す — 拘束の強さの窓は狭い。弱いと自重で崩れ、強いとぶつけても壊れない\",\"href\":\"log_fx.html#exp085\"},\"086\":{\"title\":\"葉を風で舞わせる — 乱れは Amplitude で広がり、Swirl Size で渦の大きさが変わる\",\"href\":\"log_fx.html#exp086\"},\"087\":{\"title\":\"ターンテーブルで見せる — 形は物を回してもカメラを回しても同じ。変わるのは光だけ\",\"href\":\"log.html#exp087\"},\"088\":{\"title\":\"文字を光らせる — 明るさは頭打ち、こぼれる光と時間だけが増える\",\"href\":\"log_fx.html#exp088\"},\"089\":{\"title\":\"落ち葉を積もらせる — 積もるかどうかは Response で決まる。摩擦では止まらない\",\"href\":\"log_fx.html#exp089\"},\"090\":{\"title\":\"061〜090 の振り返り点検 — 7件を測り直して全部一致。訂正は2件、黙って無視される設定は8件に\",\"href\":\"log.html#exp090\"},\"091\":{\"title\":\"面を半分にすると、形のずれはおよそ2倍になる — 25%まで減らしてもずれは幅の0.119%\",\"href\":\"log.html#exp091\"},\"092\":{\"title\":\"辺の長さを半分にすると、面は約4倍・ずれは約1/4・時間は約4倍\",\"href\":\"log.html#exp092\"},\"093\":{\"title\":\"ならしても体積はほとんど減らない — 強さ160でも99.60%、縮みは0.40%だけ\",\"href\":\"log.html#exp093\"},\"094\":{\"title\":\"升目を半分にしても、数は8倍ではなく約4倍 — VDBは表面の近くだけ持っている\",\"href\":\"log.html#exp094\"},\"095\":{\"title\":\"隙間 0.01 の継ぎ目は、Snap Distance が 0.01 になって初めて閉じる — 0.0095 では閉じない\",\"href\":\"log.html#exp095\"},\"096\":{\"title\":\"Force Total Count はぴったり合う — 10通り試して差は1つも出なかった\",\"href\":\"log.html#exp096\"},\"097\":{\"title\":\"pack を入れると、点は362分の1・ファイルは198分の1になる — 1万個で 22.5MB が 0.114MB\",\"href\":\"log.html#exp097\"},\"098\":{\"title\":\"boolean は答えと6桁まで一致する — 差の正体は円ではなく多角形だった\",\"href\":\"log.html#exp098\"},\"099\":{\"title\":\"立方体を割り続けると、体積は約32.76%に落ち着く — bilinear だけはちょうど1.000000のまま\",\"href\":\"log.html#exp099\"},\"100\":{\"title\":\"peak は式どおりに動く — 球は((r+d)/r)³、立方体は(1+2d/√3)³に6桁一致\",\"href\":\"log.html#exp100\"},\"101\":{\"title\":\"面積の測りは、平らな面ならぴったり合う — 球の足りない分は分割の2乗で減る\",\"href\":\"log.html#exp101\"},\"102\":{\"title\":\"押し出した体積は式どおり — 面積×距離、Inset を入れても四角錐台の式に6桁一致\",\"href\":\"log.html#exp102\"},\"103\":{\"title\":\"Rotate Order の xyz は「x から順に掛ける」 — 6通りで最大 0.725534（約42.5°）ずれる\",\"href\":\"log.html#exp103\"},\"104\":{\"title\":\"resample の点の数は切り上げ — 「最大の長さ」は本当に最大だった\",\"href\":\"log.html#exp104\"},\"105\":{\"title\":\"spiral の長さは折れ線の式に6桁一致 — 1巻き50分割で 0.06% 短い\",\"href\":\"log.html#exp105\"},\"106\":{\"title\":\"attribrandomize の分布は式どおり — Scale Around Middle は標準偏差だった\",\"href\":\"log.html#exp106\"},\"107\":{\"title\":\"extractcentroid の Center of Mass は、閉じていれば体積・開いていれば面積の中心\",\"href\":\"log.html#exp107\"},\"108\":{\"title\":\"triangulate2d の三角形は 2n−2−h 枚 — 9通りすべて式どおり、面積は凸包と一致\",\"href\":\"log.html#exp108\"},\"109\":{\"title\":\"groupexpand の1段は「隣」の決め方しだい — 点と辺共有は菱形、面の既定は正方形\",\"href\":\"log.html#exp109\"},\"110\":{\"title\":\"copyxform は「1回分をくり返す」ではなく「値を i 倍して1回かける」 — 回転＋移動は輪にならない\",\"href\":\"log.html#exp110\"},\"111\":{\"title\":\"pointjitter の Scale は「幅」 — 各軸 −s/2〜+s/2 の一様で、箱の中に散る\",\"href\":\"log.html#exp111\"},\"112\":{\"title\":\"vdbcombine の和・積・差は球2つの式に収束 — ボクセル 0.0125 で 0.08% 以内、どれも少なめ\",\"href\":\"log.html#exp112\"},\"113\":{\"title\":\"timeblend は速度が無ければ直線、あれば F² を誤差0でつなぐ — v は「1秒あたり」\",\"href\":\"log.html#exp113\"},\"114\":{\"title\":\"sweep の管は曲がり角で細る — 不足は 1−cos(角/2)、Stretch Around Turns で A×L に一致\",\"href\":\"log.html#exp114\"},\"115\":{\"title\":\"attribfill の到着時間は「網の辺をたどる道のり」 — 四角の網ではマンハッタン距離そのもの\",\"href\":\"log.html#exp115\"},\"116\":{\"title\":\"uvflatten は円筒をゆがみ0.0001%で開く — 半球は SCP 13%・ABF 10% ゆがむ\",\"href\":\"log.html#exp116\"},\"117\":{\"title\":\"relax は点を 2×pscale 近くまで離す — 余裕があれば97%、詰め込みに近いと73〜77%\",\"href\":\"log.html#exp117\"},\"118\":{\"title\":\"revolve の面積・体積は k 角の式に6桁一致 — ただし閉じた断面を回すと体積がマイナス（裏返し）\",\"href\":\"log.html#exp118\"},\"119\":{\"title\":\"面に沿った距離は Surface が正解 — Edge と attribfill は辺の道のり、Heat は約1%短い\",\"href\":\"log.html#exp119\"},\"120\":{\"title\":\"measurethickness は殻の厚みを6桁で返す — 板の縁ではぼかしで細く出る。box の Use Divisions は面にならない\",\"href\":\"log.html#exp120\"},\"121\":{\"title\":\"091〜120 の振り返り点検 — 30本すべて流し直し、結果の数字は1つを除いて全部一致\",\"href\":\"log.html#exp121\"},\"122\":{\"title\":\"polyexpand2d は角を丸めずに尖らせる — 20°の鋭い角でも。Divisions は距離を等分する\",\"href\":\"log.html#exp122\"},\"123\":{\"title\":\"shrinkwrap は凸包そのもの — 中の点をいくら足しても立方体は体積1.000000、同じ平面の三角形はまとめる\",\"href\":\"log.html#exp123\"},\"124\":{\"title\":\"L-System のコッホ曲線は式どおり — 全長4^n・端の間隔3^n。小数の世代は途中の形になる\",\"href\":\"log.html#exp124\"},\"125\":{\"title\":\"点と面の数は式で先に分かる — divide は n−2、convertline は V+F−2。edgedivide は既定で点が2倍\",\"href\":\"log.html#exp125\"},\"126\":{\"title\":\"cluster（k-means）は塊を理論の上限どおりに分ける — 重なる塊でも Φ(s/σ)² と1%以内\",\"href\":\"log.html#exp126\"},\"127\":{\"title\":\"findshortestpath の道のりは Edge の距離と同じ — 四角の網では |x|+|z|\",\"href\":\"log.html#exp127\"},\"128\":{\"title\":\"extracttransform は移動と回転だけを取り出す — 拡大は捨てて distortion に出す\",\"href\":\"log.html#exp128\"},\"129\":{\"title\":\"measure の曲率は既定のままだと式と合わない — Divide Element Area を入れると球・円柱とも0.03%以内\",\"href\":\"log.html#exp129\"},\"130\":{\"title\":\"normal の Cusp Angle は「曲がり角がこれより大きければ角を立てる」 — ちょうど等しいと、なめらか\",\"href\":\"log.html#exp130\"},\"131\":{\"title\":\"bend は長さを保って円弧に曲げる — 端の位置は式と差0、範囲の外は接線の向きにまっすぐ\",\"href\":\"log.html#exp131\"},\"132\":{\"title\":\"attribpromote の11通りのまとめ方 — Median は偶数個なら上の方、Mode は同数なら最小の値\",\"href\":\"log.html#exp132\"},\"133\":{\"title\":\"ray の Direction には最初から @N の式が入っている — Python で set しても変わらず、真下に落ちなかった\",\"href\":\"log.html#exp133\"},\"134\":{\"title\":\"最初から式が入っているつまみは SOP 全体で488個 — set しても式が残り、値は変わらない\",\"href\":\"log.html#exp134\"},\"135\":{\"title\":\"VEX のノイズの値の範囲 — noise() は 0.06〜0.92 にしか届かず、snoise() は ±1 を超える\",\"href\":\"log.html#exp135\"},\"136\":{\"title\":\"nearpoints は自分を先頭に数え、近い順に返す — 半径ちょうど1は入るが、ちょうど√2は入らなかった\",\"href\":\"log.html#exp136\"},\"137\":{\"title\":\"VEX の fit は範囲の外で止まり、efit と lerp は伸び続ける — smooth は 3x²−2x³\",\"href\":\"log.html#exp137\"},\"138\":{\"title\":\"vdbfrompolygons の SDF は帯の中だけ本当の距離（ずれ0.0008以下）— 帯の外は ±（Band Voxels×ボクセル）で平ら\",\"href\":\"log.html#exp138\"},\"139\":{\"title\":\"attribblur の1回は「となりの平均へ半分近づく」を2度 — ぼけ幅は √回数。線では Pin Border で全く動かない\",\"href\":\"log.html#exp139\"},\"140\":{\"title\":\"copytopoints の向きは orient が N に勝つ — N は +z を、up は +y を合わせる。scale と pscale は掛け算\",\"href\":\"log.html#exp140\"},\"141\":{\"title\":\"pointsfromvolume の点は、格子なら1点 s³・四面体なら s³/√2 — 箱では面の上にも並ぶ\",\"href\":\"log.html#exp141\"},\"142\":{\"title\":\"platonic の Radius は、四面体・八面体・二十面体では頂点までの距離 — 立方体は辺が1、十二面体は0.9933\",\"href\":\"log.html#exp142\"},\"143\":{\"title\":\"circle の Polygon は頂点が円周に乗る正 n 角形 — 弧の Divisions は辺の数\",\"href\":\"log.html#exp143\"},\"144\":{\"title\":\"torus の Rows は管の断面、Columns は大きな輪 — 体積は2つの内接多角形の積で決まる\",\"href\":\"log.html#exp144\"},\"145\":{\"title\":\"mirror の継ぎ目は「元と鏡像の距離」が Consolidate Seam 未満ならまとまる — 境目ちょうどはまとまらない\",\"href\":\"log.html#exp145\"},\"146\":{\"title\":\"clip で切った球の面積は 2πh — 比は切る高さに関係なく、球全体と同じだけずれる\",\"href\":\"log.html#exp146\"},\"147\":{\"title\":\"twist SOP の6つの操作 — 体積を保つのは Shear だけ。Squash は長さ (1+s) 倍・太さ 1/(1+s) 倍\",\"href\":\"log.html#exp147\"},\"148\":{\"title\":\"tube の円錐台は式 × 内接多角形の比 — Radius の1つ目が上、円錐の先は点が重なったまま\",\"href\":\"log.html#exp148\"},\"149\":{\"title\":\"divide の Bricker は形の端（＋ Offset）から Size おきに線を引く — Convex は n 角形を n−2 枚の三角形か、その半分の四角形に\",\"href\":\"log.html#exp149\"},\"150\":{\"title\":\"122〜149 の振り返り点検 — 28本すべて流し直し、時間以外の数字は全部一致\",\"href\":\"log.html#exp150\"},\"151\":{\"title\":\"sphere の Polygon は点 10f²+2・面 20f² の測地球 — 同じ点の数なら Polygon Mesh より体積の不足が約3割小さい\",\"href\":\"log.html#exp151\"},\"152\":{\"title\":\"polybevel の Round は、分割を増やすと「角を丸めた箱」の体積に近づく — 平らな面取りは 1 − 6d² + (16/3)d³\",\"href\":\"log.html#exp152\"},\"153\":{\"title\":\"neighbourcount() の合計の半分は辺の数 — そこから出した V − E + F は、板 1・球と箱 2・トーラスと筒 0\",\"href\":\"log.html#exp153\"},\"154\":{\"title\":\"polyfill の四角形の塞ぎ方は、辺が奇数の穴を塞がない — 三角形は 1つの穴に n−2 枚、Grid は少しふくらむ\",\"href\":\"log.html#exp154\"},\"155\":{\"title\":\"scatter の density 属性は点を k/(1+k) に分ける — 数を決めないと Density Scale × 面積のあたりで揺れる\",\"href\":\"log.html#exp155\"},\"156\":{\"title\":\"polywire の管は Wire Radius に内接する正 n 角柱で両端に蓋 — 折れ目は Prevent Joint Buckling で r/cos(θ/2) に広がる\",\"href\":\"log.html#exp156\"},\"157\":{\"title\":\"voronoifracture は種 N 個で N 個のかけら、体積の合計は元のまま — 切り口を作らないと、中のかけらは消える\",\"href\":\"log_fx.html#exp157\"},\"158\":{\"title\":\"種を relax すると、voronoifracture のかけらはそろうどころかばらつく — 種が箱の壁へ押し出される\",\"href\":\"log_fx.html#exp158\"},\"159\":{\"title\":\"trail の速さは1秒あたり、差分の式どおり — 加速度は Central Difference のときだけ出て、Velocity Scale の2乗で縮む\",\"href\":\"log_fx.html#exp159\"},\"160\":{\"title\":\"uvlayout は長方形 12 枚で升の 48〜84% を埋める — Padding は Search Resolution が粗いほど大きく効く\",\"href\":\"log.html#exp160\"},\"161\":{\"title\":\"attribtransfer は Distance Threshold までそのまま運び、Blend Width の外側で (1 − t²)² に落とす\",\"href\":\"log.html#exp161\"},\"162\":{\"title\":\"subdivide の crease は「重み w の回数までは尖ったまま」— w ≥ Iterations なら箱はそのまま、体積 1\",\"href\":\"log.html#exp162\"},\"163\":{\"title\":\"vellumconstraints の Cloth は網を三角形にしてから、辺ごとに伸びの拘束、内側の辺ごとに曲げの拘束を作る\",\"href\":\"log_fx.html#exp163\"},\"164\":{\"title\":\"vdbfromparticles の粒は pscale を半径にした球 — 2つ重ねると「2つの球の和」の体積に、升目の2乗で近づく\",\"href\":\"log.html#exp164\"},\"165\":{\"title\":\"POP の粒は、生まれたフレームで 1 ステップ先に進む — 1 秒後の落下は Substeps 1 で 13% 多く、誤差は Substeps に反比例して縮む\",\"href\":\"log_fx.html#exp165\"},\"166\":{\"title\":\"popdrag の終端速度は g/k ではなく √(g/k) に近づく — 速さの2乗に比例する抵抗と同じ振る舞い\",\"href\":\"log_fx.html#exp166\"},\"167\":{\"title\":\"rbdbulletsolver の箱は地面ぴったりで止まる — Collision Padding を変えても止まる高さは同じ、当たった瞬間だけ少し沈む\",\"href\":\"log_fx.html#exp167\"},\"168\":{\"title\":\"heightfield_noise の Amplitude は高さの幅ではない — 幅は Amplitude の 23〜29%、Center Noise を切ると Amplitude の半分だけ上がる\",\"href\":\"log.html#exp168\"},\"169\":{\"title\":\"heightfield_erode は土の量を保たない — 40 フレームで height の平均が 5 下がり、削れた分の大半は地形から消える\",\"href\":\"log_fx.html#exp169\"},\"170\":{\"title\":\"Vellum の布は既定の硬さでも Substeps 1 で 2% 伸びる — Substeps 1 では 10^4 と 10^10 の差が出ない\",\"href\":\"log_fx.html#exp170\"},\"171\":{\"title\":\"curlnoise() はほぼ湧き出しのない流れ — 発散は、ふつうのノイズの約 3.5 万分の 1（周波数 1）\",\"href\":\"log.html#exp171\"},\"172\":{\"title\":\"curlnoise で流した粒は混み具合をほぼ保つ — ふつうのノイズで流すと、平均で2倍以上に固まる\",\"href\":\"log.html#exp172\"},\"173\":{\"title\":\"同じ計算でも VEX（点ごと）は Detail のループの約170倍、Python の約260倍速い — 100 万点で 1.3 ミリ秒\",\"href\":\"log.html#exp173\"},\"174\":{\"title\":\"for-each はかけら1つあたり約 0.037 ミリ秒 — compile block で 35% 速く、wrangle 1つにまとめれば 30 倍速い\",\"href\":\"log.html#exp174\"},\"175\":{\"title\":\"popwind の粒は、風との速さの差が 5/(1 + 5·k·t) で縮む — 差の2乗に比例する抵抗を、Substeps によらずぴったり解いている\",\"href\":\"log_fx.html#exp175\"},\"176\":{\"title\":\"heightfield_noise の高さの幅は、地面に入る模様の数で決まる — Element Size を地面の 1/20 にすると Amplitude の 6 割\",\"href\":\"log.html#exp176\"},\"177\":{\"title\":\"Vellum の布の伸びは、Substeps より Constraint Iterations を上げる方が安く減る — 400 回で 0.2%、1600 回で 0.002%\",\"href\":\"log_fx.html#exp177\"},\"178\":{\"title\":\"pcfind の時間は「見つかった点の数」で決まる — 半径を広げても、最大の数を 10 に絞れば 1 点 0.1 マイクロ秒\",\"href\":\"log.html#exp178\"},\"179\":{\"title\":\"止まった空気の popwind と重力は、popdrag とぴったり同じ落ち方 — Substeps で差が出るのは重力と組み合わせたとき。Wind Speed は掛け算\",\"href\":\"log_fx.html#exp179\"},\"180\":{\"title\":\"151〜179 の振り返り点検 — 29本すべて流し直し、時間以外の数字は全部一致\",\"href\":\"log.html#exp180\"},\"181\":{\"title\":\"pcfind と nearpoints は同じ結果・同じ速さ — pcopen + pcfilter は 1.6 倍遅く、距離で重みを付けた平均になる\",\"href\":\"log.html#exp181\"},\"182\":{\"title\":\"pcfilter の重みは「半径に対する距離」だけでは決まらない — 見つかった点どうしの並びで変わり、式は分からなかった\",\"href\":\"log.html#exp182\"},\"183\":{\"title\":\"rbdbulletsolver の沈み込みは Bullet Substeps で決まる — 1 だと 0.38 めり込んで沈んだまま、50 でほぼ 0\",\"href\":\"log_fx.html#exp183\"},\"184\":{\"title\":\"mpmsource は箱に「体積 ÷ Particle Separation³」個の粒を詰める — pscale には Separation そのものが入る\",\"href\":\"log_fx.html#exp184\"},\"185\":{\"title\":\"smooth の縮み方は r = 1/(1 + Strength·L^q/C(2q, q)) — 36 通りで6桁一致。Filter Quality を上げるほど形を保つ\",\"href\":\"log.html#exp185\"},\"186\":{\"title\":\"smooth の3つの Method は、点が等間隔の円では同じ縮み方 — 開いた線の端は Constrained Boundary で止まり、波の高さは 1/(1 + S·L/2) だけ残る\",\"href\":\"log.html#exp186\"},\"187\":{\"title\":\"点の間隔がそろわない円では、smooth は粗い側を大きく縮める — 3つの Method の差は小さく、どれも丸さを保たない\",\"href\":\"log.html#exp187\"},\"188\":{\"title\":\"hairgen の毛の本数は Density × 面積 — 1本は Segments + 1 点、長さは Length ちょうど\",\"href\":\"log.html#exp188\"},\"189\":{\"title\":\"箱 100 個を USD にすると、パックしなければメッシュ 1 つ、Point Instancer なら 6 プリム、Xforms なら 202 プリム\",\"href\":\"log.html#exp189\"},\"190\":{\"title\":\"箱 1 万個の USD — Point Instancer は 0.32 MB・8 ミリ秒、Native Instances は 4.6 倍、Unpack は 7.4 倍の大きさ\",\"href\":\"log.html#exp190\"},\"191\":{\"title\":\"多角形の球のいちばん深いへこみは sin²(Δ/2) — 分割を倍にするたびに 1/4、平均はその 0.56 倍\",\"href\":\"log.html#exp191\"},\"192\":{\"title\":\"polyextrude の Inset は上の面を i だけ内側へ寄せる — 体積は角錐台の式どおり、i ≥ 0.5 で四角錐になり、それ以上は裏返らない\",\"href\":\"log.html#exp192\"},\"193\":{\"title\":\"popsource の Constant Birth Rate は1秒あたり — 端数の粒はフレームごとに運で決まり、Life 0.5 秒の粒は 11 フレームで消える\",\"href\":\"log_fx.html#exp193\"},\"194\":{\"title\":\"POP の粒が数えられるフレームは Life × fps − 1/Substeps — 0.5 秒の粒は Substeps 1 で 11 フレーム、4 で 11.75\",\"href\":\"log_fx.html#exp194\"},\"195\":{\"title\":\"vdbreshapesdf の Dilate・Erode は、球の半径を Offset × 升の大きさだけ変える — Iterations は効かず、Open・Close は形をほぼ変えない\",\"href\":\"log.html#exp195\"},\"196\":{\"title\":\"vdbreshapesdf の Open は箱の角を r より少し大きく丸める — Close も凸な箱を少しだけ削る\",\"href\":\"log.html#exp196\"},\"197\":{\"title\":\"SDF の帯を 25 升に広げると、vdbreshapesdf の Close は箱をほとんど削らなくなる — Open の丸みはかえって大きくなる\",\"href\":\"log.html#exp197\"},\"198\":{\"title\":\"vdbreshapesdf の Open で丸めた辺の断面は円弧 — 半径は Offset × 升より 2.5〜3.2 升大きい\",\"href\":\"log.html#exp198\"},\"199\":{\"title\":\"Open で丸めた辺の半径が約 3 升大きいのは、SDF の帯のせいではない — 帯 3〜25 升で足し分は変わらない\",\"href\":\"log.html#exp199\"},\"200\":{\"title\":\"FLIP のダムブレイクは Particle Separation 0.04 で足りる — 0.06 より粗いと壁ぎわの数粒が大きな塊に見え、水も 1〜2 割増える\",\"href\":\"log_fx.html#exp200\"},\"201\":{\"title\":\"Pyro で焚き火の炎（高さ 1.2 m）を作るなら Flame Lifespan 0.25・Buoyancy 0.25・Cooling Rate 1 — 揺らすのは Turbulence で、Use Control Field を切る\",\"href\":\"log_fx.html#exp201\"},\"202\":{\"title\":\"焚き火の Pyro を速く回すなら Voxel Size を 0.02 → 0.04 に — 5.1 倍速く、炎の高さの差は 3%。速度の升だけ粗くするのと Substeps 2 は、かえって遅い\",\"href\":\"log_fx.html#exp202\"},\"203\":{\"title\":\"氷の入ったグラスを Karma で撮ると、サンプル1つあたり不透明の 6 倍の時間がかかる — 重ねた水と氷は +27% だけ。16 サンプル＋ノイズ除去なら約 3 分\",\"href\":\"log.html#exp203\"},\"204\":{\"title\":\"焚き火の Pyro のキャッシュは、9 割以上が速度（vel）— vel を煙のある所だけに残して VDB・16 bit にすると 16 分の 1、描画に使う値のずれは 0.00025\",\"href\":\"log_fx.html#exp204\"},\"205\":{\"title\":\"Karma のぼけ（被写界深度）とぶれ（モーションブラー）は、時間を +5%〜9% しか増やさない — ざらつきを消すのはサンプル数ではなくノイズ除去。16 サンプル＋OIDN で 27 秒\",\"href\":\"log.html#exp205\"},\"206\":{\"title\":\"テーブルクロスを粗い布で試すなら 44×56 まで — 落ち方の差は平均 1.9 cm で、計算は 39 秒（実践の細かさの 39%）。ただし粗いほど角の垂れが短く、22×28 では 17 cm 高い\",\"href\":\"log_fx.html#exp206\"},\"207\":{\"title\":\"焚き火を Karma で撮るとき、Volume Step Rate を 0.25 から下げても速くならず、1 に上げると遅い — 1920×1080 では 1 が 45 秒、0.125 が 36 秒。Pyro を粗くしても撮る時間は同じで、炎の形だけ変わる\",\"href\":\"log.html#exp207\"},\"208\":{\"title\":\"FLIP の水を面にするとき、形を決めるのは Influence Scale と Method — Spherical はつぶつぶ、Influence 5 は体積 87%。なめらかにするなら Filtering（既定の 1.3 倍の時間）\",\"href\":\"log_fx.html#exp208\"},\"209\":{\"title\":\"焚き火を 8 通り回すなら、PDG で同時に 8 本が 1.6 倍速い — ただし同時に 1 本だと 2.2 倍遅く、2 本でほぼ並ぶ。Evaluate Using を Frame Range にしないと 1 フレームしか回らない\",\"href\":\"log.html#exp209\"},\"211\":{\"title\":\"テーブルクロスが机から浮くのは Thickness の分だけ — 既定 0.01 で 10 mm 浮く。0.0025 まで薄くしてもめり込まず、Calculate Uniform（辺の長さ × 0.25）なら 2.8 mm\",\"href\":\"log_fx.html#exp211\"},\"212\":{\"title\":\"金属の Roughness は 0.2 まで見た目がほぼ同じ — ハイライトが広がり始めるのは 0.3 から。0.5 で明るさ 36%・広さ 1.4 倍、0.7 で 15%・2.4 倍\",\"href\":\"log.html#exp212\"},\"213\":{\"title\":\"SSS で透けて見せるなら、半径 0.5 の球では Subsurface Distance 0.1〜0.3 — 0.3 のとき逆光の真ん中が 5.3 倍明るい。1 にするとかえって暗く、正面から見ても 41% に沈む\",\"href\":\"log.html#exp213\"},\"214\":{\"title\":\"Karma のぼけの大きさは f²(d−s)/(N·d·s) に 0.9% 以内で一致 — F を半分にすると直径は倍。写真の薄いレンズの式より約 5% 小さい\",\"href\":\"log.html#exp214\"},\"216\":{\"title\":\"煙の透け具合は光の吸収の式 exp(−Density Scale × 濃さ × 厚み[m]) どおり — Density Scale を倍にすると、届く光は 2 乗に減る。ただし Volume Step Rate 0.25（既定）では濃い煙が少し明るく出て、1 で式とぴったり\",\"href\":\"log.html#exp216\"},\"217\":{\"title\":\"テーブルクロスの曲げの硬さは、既定 0.1 から下げても形はほぼ同じ（差 1.1 cm）。10 に上げると布が張って机から 15 cm 張り出し、裾が 4 cm 上がる\",\"href\":\"log_fx.html#exp217\"},\"210\":{\"title\":\"181〜209 の点検 — 29 本を流し直して 35,969 個の値を突き合わせた。22 本は完全に一致。201 は台本が 202 の変更に引きずられていたので直したが、Turbulence の 2 条件はまだ合わない\",\"href\":\"log.html#exp210\"},\"218\":{\"title\":\"海の光の道は、Roughness を上げると太い白い帯になり（0.02→0.15 で幅 15→61 列）、さざ波を高くすると粒のまま広がる（0.4→3.2 で 12→36 列）\",\"href\":\"log_fx.html#exp218\"},\"219\":{\"title\":\"海の板の点を半分にすると、撮る時間は 12% 減り、きらめきの粒も 15% 減る。1/4 で時間 23% 減・粒 27% 減。1/16 でも時間は 64% までしか減らない\",\"href\":\"log_fx.html#exp219\"},\"220\":{\"title\":\"焚き火の Turbulence は、Use Control Field を入れると効かない（揺らぎなしと全フレーム同じ）。切ると炎の高さ 1.31 m（なし 1.21 m）。実験201 の結論は正しく、点検で合わなかったのは revertToDefaults が Use Control Field を「切り」に戻したため\",\"href\":\"log_fx.html#exp220\"},\"215\":{\"title\":\"草を Karma で撮るならパックしたまま（1 万本 17 秒、解くと 128 秒）。ただし 10 万本は、ポイントインスタンサーにしても、地面を広げて混み具合を 1 万本と同じにしても 13 分かかった\",\"href\":\"log.html#exp215\"},\"221\":{\"title\":\"海の映像の 1 枚は、サンプル数を 16→4 にしても 8.8→7.2 秒、解像度を 640×360 にしても 8.3 秒。時間の大半は画の大きさによらない分で、下げるなら 4 サンプル＋ノイズ除去\",\"href\":\"log_fx.html#exp221\"},\"222\":{\"title\":\"草を何万本も Karma で撮るなら、Solaris（LOP）の sopimport で「Create Point Instancer」にして撮る。10 万本が 793 秒 → 12 秒、100 万本も 37 秒\",\"href\":\"log.html#exp222\"},\"223\":{\"title\":\"海の白波の cusp のしきい値は、風 5 m/秒で 0.08・10 m/秒で 0.15・15 m/秒で 0.26（波の高さを本物に合わせたとき）。0.55 では風 15 m/秒でもほぼ白波が出ない\",\"href\":\"log_fx.html#exp223\"},\"224\":{\"title\":\"Vellum の布の伸びは Substeps で決まる（1→5 で平均 2.8%→0.10%）。Constraint Iterations を 4 倍にするより Substeps を倍にする方が、短い時間でよく効く。布の目を細かくすると 4 倍伸びる\",\"href\":\"log_fx.html#exp224\"},\"225\":{\"title\":\"明かりを何百も置く場面は、照らすのをライトで。1000 個でも 16 サンプル 28 秒・ざらつき 5%。小さな光る球で照らすと、ざらつき 54% で、64 サンプルでも光が拾いきれない\",\"href\":\"log.html#exp225\"},\"226\":{\"title\":\"ガラスのひびを増やすと、同じつながりの強さでは割れにくくなる（20 本で破片の 17% が動いたのが、80 本では 5%）。80 本なら強さを 0.8 → 0.6 に下げると同じくらい割れる。計算はどれも 3 秒以内\",\"href\":\"log_fx.html#exp226\"},\"227\":{\"title\":\"地形を削る heightfield_erode は、既定の 5 フレームでもう谷筋が刻まれる。20 フレームで谷の出口に土砂が広がり、100 フレームでは谷が埋まって山が低くなる（高さのばらつき 29 → 18 m）。時間はどれも 3 秒以内\",\"href\":\"log.html#exp227\"},\"228\":{\"title\":\"粒は点のまま Karma に渡す。1000 万個でも 8 秒（640×360・8 サンプル）。小さな球をパックして並べると 3 万個で 78 秒かかり、その 8 割は場面を渡す時間\",\"href\":\"log.html#exp228\"},\"229\":{\"title\":\"毛は曲線のまま Karma に渡す。100 万本でも 12 秒（640×360・8 サンプル）。polywire で筒の面にすると 1 本あたりが重く、3 万本で 9 秒\",\"href\":\"log.html#exp229\"},\"230\":{\"title\":\"速く回る物のブレは、オブジェクトごと回すなら既定（Rotation Blur・2 サンプル）で弧になる。SOP で形を回すと既定の Geometry Time Samples 2 ではまっすぐな線になり、8 で弧になる。時間はほぼ同じ\",\"href\":\"log.html#exp230\"}}";s.parentNode.insertBefore(e,s);})();
